/* One bottom caption owns all transient tips/notifications. No centre fallback. */
static const char*ui_context_tip40(const Combat*g,const WindowUI*u,int help){
 if(g->tooltipsDisabled||u->equipPicker49)return NULL;
 if(u->active&&u->inside&&!u->placing&&u->tipTime>0){int w=u->focus-5,c=u->choice[w];if(c<0)return "A: close this window. B: window selection.";if(w==UI_QUESTS)return "A: track/untrack quest. Right stick moves the highlighted frame; L3 resets it.";if(w==UI_SKILLS)return skillDefs[class_skill(g,c)].help;if(w==UI_ITEMS){int id=ui_owned_item47(g,c);return id>=0?(g->jobId>=J60_NINJA&&ammo_rule60(itemDefs[id].id)?"X: select this ammunition; X again: automatic selection. Y: item details.":itemDefs[id].description):"Inventory is empty.";}if(w==UI_EQUIP){int id=inventory_slot46(g,c);return id>=0?itemDefs[id].description:"A: choose equipment for this slot.";}static const char*effects[6]={"STR increases physical damage.","AGI raises evasion and shortens attack delay.","VIT increases HP and defence.","INT increases SP and spell damage.","DEX raises accuracy and bow damage.","LUK increases critical chance."};return effects[c];}
 if(!u->active||!help)return NULL;
 return u->placing?"D-pad: position  A: drop  Y: clear  B: cancel":!u->inside?(u->focus>=5?"Right stick: move  L3: reset  A: enter  R3: close  B: play":"D-pad: window  A: open  B: play"):u->focus==5?"D-pad: stat  A: raise  R3: close  B: back":u->focus==8?"X: learn  A: assign  Y: info  R3: close":u->focus==6?"D-pad: item  A: assign  X: use  Y: info  R3: close":"D-pad: equipment  A: choose gear  Y: info  R3: close  B: back";
}
static void ui_caption40(const Combat*g,const char*text,int placing){if(!text||!*text)return;static char last[160];static float at;int width=placing?332:496,y=placing?380:412;if(strcmp(last,text)||g->time<at){snprintf(last,sizeof(last),"%s",text);at=g->time;}char lines[8][96];int n=ui_wrap(text,lines,width-16,1);if(n){const char*line=lines[(int)((g->time-at)/2)%n];if(placing)ui_fixed_popup(72,y,line,width,1);else{int fit=(int)ui_text_width(line,1)+16;if(fit>width)fit=width;if(fit<32)fit=32;hud_panel(72,y,fit,20);ui_scaled(80,y+1,1,"%s",line);}}}
static void ui_feedback40(const Combat*g,const WindowUI*u,const char*help,const char*message,const char*selection,int showHelp){
 if(u->equipPicker49)return;const char*text=message&&*message&&(!g->logIsTip||!g->tooltipsDisabled)&&(message!=g->log||combat_popup_visible(g))?message:NULL;
 if(!text)text=ui_context_tip40(g,u,showHelp);
 if(!text&&!g->tooltipsDisabled)text=selection&&*selection?selection:help;
 ui_caption40(g,text,u->placing);
}
