static void ui_spell_callout41(const Combat*g,float headX,float headTop){if(g->popupDisabled&POP_SPEECH)return;int id=combat_casting(g)?g->spellCastId:g->time-g->fxAt>=0&&g->time-g->fxAt<.8f?g->fxSkill:0;if(id<=0||id>=SKILL_COUNT||g->hp<=0)return;char line[96];snprintf(line,sizeof(line),"%s !!",skillDefs[id].name);int w=ui_text_width(line,.75f)+10;if(w>300)w=300;int x=(int)floorf(headX-w*.5f),y=(int)floorf(headTop-30);if(x<2)x=2;if(x+w>638)x=638-w;if(y<2)y=2;pb_fill(x,y,w,15,0x70000000);ui_light(x+5,y+1,.75f,line);}
